import sys

s = sys.stdin.read().split()[0]
n = len(s)
found = []
i = 0
while i < n:
    if s[i] == 'b':
        j = i
        while j < n and s[j] == 'b':
            j += 1
        if (j - i) not in found:
            found.append(j - i)
        i = j
    else:
        i += 1
print(len(found))

